class Zipper:
    def __init__(self, tree, breadcrumbs=()):
        self._tree = tree
        self._breadcrumbs = breadcrumbs

    @staticmethod
    def from_tree(tree):
        return Zipper(tree)

    def value(self):
        return self._tree["value"]

    def set_value(self, value):
        tree = dict(self._tree)
        tree["value"] = value
        return Zipper(tree, self._breadcrumbs)

    def left(self):
        child = self._tree.get("left")
        if child is None:
            return None
        breadcrumb = (self._tree["value"], self._tree.get("right"), "left")
        return Zipper(child, self._breadcrumbs + (breadcrumb,))

    def set_left(self, tree):
        updated = dict(self._tree)
        updated["left"] = tree
        return Zipper(updated, self._breadcrumbs)

    def right(self):
        child = self._tree.get("right")
        if child is None:
            return None
        breadcrumb = (self._tree["value"], self._tree.get("left"), "right")
        return Zipper(child, self._breadcrumbs + (breadcrumb,))

    def set_right(self, tree):
        updated = dict(self._tree)
        updated["right"] = tree
        return Zipper(updated, self._breadcrumbs)

    def up(self):
        if not self._breadcrumbs:
            return None

        value, sibling, direction = self._breadcrumbs[-1]
        if direction == "left":
            parent = {"value": value, "left": self._tree, "right": sibling}
        else:
            parent = {"value": value, "left": sibling, "right": self._tree}
        return Zipper(parent, self._breadcrumbs[:-1])

    def to_tree(self):
        zipper = self
        while zipper._breadcrumbs:
            zipper = zipper.up()
        return zipper._tree

