def encode(numbers):
    encoded = []
    for number in numbers:
        if number == 0:
            encoded.append(0)
            continue

        groups = []
        while number:
            groups.append(number & 0x7F)
            number >>= 7

        for group in reversed(groups[:-1]):
            encoded.append(group | 0x80)
        encoded.append(groups[-1])

    return encoded


