import secrets
import string
import threading


class Robot:
    _used_names = set()
    _lock = threading.Lock()
    _letters = string.ascii_uppercase
    _digits = string.digits
    _name_space_size = 26 * 26 * 1000

    def __init__(self):
        self._name = None

    @property
    def name(self):
        if self._name is None:
            with Robot._lock:
                if len(Robot._used_names) >= Robot._name_space_size:
                    raise RuntimeError("No unique robot names remain")
                while True:
                    candidate = (
                        secrets.choice(Robot._letters)
                        + secrets.choice(Robot._letters)
                        + "".join(secrets.choice(Robot._digits) for _ in range(3))
                    )
                    if candidate not in Robot._used_names:
                        Robot._used_names.add(candidate)
                        self._name = candidate
                        break
        return self._name

    def reset(self):
        with Robot._lock:
            if self._name is not None:
                Robot._used_names.discard(self._name)
                self._name = None
